import { useEffect } from 'react';
import { batch, useDispatch, useSelector } from 'react-redux';
import { Link, useNavigate, useParams } from 'react-router-dom';
import styled from 'styled-components';

import {
  melodies,
  melodiesActions,
  selectLibraryMelodies,
  selectMelodies,
} from 'app/services/MelodiesService';
import {
  getMelodyBpm,
  useActivateMelody,
  useCurrentMelody,
} from 'app/services/MelodiesService/useCurrentMelody';
import { useMelodyPlayback } from 'app/services/MelodiesService/useMelodyPlayback';
import { useRememberMelodyOpened } from 'app/services/MelodiesService/useRememberMelodyOpened';
import { notesActions, selectNotes } from 'app/services/NotesService';
import { selectSettings, settingsActions } from 'app/services/SettingsService';
import { microtonalPreset } from 'app/services/SettingsService/microtonal';
import { scales } from 'app/services/SettingsService/scales';

import { HeaderIcon } from 'app/components/HeaderIcon';
import {
  MelodyActionButton,
  MelodyActionIcon,
} from 'app/components/MelodyAction';
import {
  MelodyEditorIcon,
  MelodyEditorPopover,
} from 'app/components/MelodyEditorAction';
import { MelodyExport } from 'app/components/MelodyExport';
import { MelodyScaleOptimization } from 'app/components/MelodyScaleOptimization';
import { RecordingEditor } from 'app/components/RecordingEditor';
import { PageWrapper } from 'app/components/_styled/PageWrapper';

import { capitalize } from 'utils';

export const MelodyPage = () => {
  const { songId } = useParams();
  const dispatch = useDispatch();
  const navigate = useNavigate();
  const source = useSelector(selectLibraryMelodies).find(
    ({ title }) => title === songId,
  );
  const { libraryEdits, librarySaveError } = useSelector(selectMelodies);
  const { melody: recording, project: recordingProject } =
    useSelector(selectNotes);
  const { isRecording } = useSelector(selectSettings);
  const original = melodies.find(({ title }) => title === songId);
  useRememberMelodyOpened(original?.title);
  useActivateMelody(source, `library:${songId}`);
  const melody = useCurrentMelody(source);

  const playback = useMelodyPlayback(melody);
  const { isPlaying, stop: stopPlayback } = playback;

  useEffect(() => {
    if (!original) {
      navigate('/melodies');
      return;
    }
    batch(() => {
      dispatch(melodiesActions.resetPlayback());
    });
    return stopPlayback;
  }, [dispatch, original, navigate, stopPlayback]);

  if (!melody) return null;
  const tonalityIndex = (melody.pitch < 0 ? 12 : 0) + melody.pitch;
  const tonality = scales.chromatic.intervals[tonalityIndex];
  const edited = !!libraryEdits[melody.title];

  return (
    <Workspace>
      <Header>
        <MelodyActionButton
          as={Link}
          to="/melodies"
          aria-label="Back to melodies"
          title="Back to melodies"
        >
          <MelodyEditorIcon icon="back" />
        </MelodyActionButton>
        <h1
          title={`${melody.author ? `${melody.author} — ` : ''}${
            melody.displayTitle ?? melody.title
          }`}
        >
          {melody.author ? `${melody.author} — ` : ''}
          {melody.displayTitle ?? melody.title}
        </h1>
        {edited && !librarySaveError && (
          <Saved
            role="status"
            aria-label="Changes saved in this browser"
            title="Changes saved in this browser"
          >
            ✓
          </Saved>
        )}
        <Actions>
          <MelodyActionButton
            $withLabel
            type="button"
            aria-label="Copy to Melody Studio"
            title={
              isRecording
                ? 'Stop recording to copy this melody'
                : 'Copy to Melody Studio'
            }
            disabled={isRecording || !melody.notes.length}
            onClick={() => {
              if (
                isRecording ||
                !melody.notes.length ||
                ((recording.notes.length || recordingProject) &&
                  !window.confirm(
                    'Replace the current recording in Melody Studio with this melody? Your unsaved recording will be lost.',
                  ))
              )
                return;
              stopPlayback();
              batch(() => {
                dispatch(notesActions.loadRecording(melody));
                dispatch(settingsActions.loadMelodySettings(melody));
              });
              navigate('/sandbox/staff', { state: { editRecording: true } });
            }}
          >
            <HeaderIcon name="sandbox" />
            Copy to Melody Studio
          </MelodyActionButton>
          <MelodyActionButton
            as={Link}
            to={`/play-along/${encodeURIComponent(melody.title)}`}
            aria-label="Practice"
            title="Practice"
          >
            <MelodyActionIcon action="practice" />
          </MelodyActionButton>
          <MelodyActionButton
            as={Link}
            to={`/karaoke/${encodeURIComponent(melody.title)}`}
            aria-label="Sing karaoke"
            title="Sing karaoke"
          >
            <HeaderIcon name="karaoke" />
          </MelodyActionButton>
          {edited && (
            <MelodyActionButton
              type="button"
              aria-label="Restore original melody"
              title="Restore original melody"
              onClick={() => {
                stopPlayback();
                dispatch(melodiesActions.restoreLibraryMelody(melody.title));
                dispatch(
                  settingsActions.loadMelodySettings({
                    ...original!,
                    bpm: getMelodyBpm(original!),
                  }),
                );
              }}
            >
              <MelodyActionIcon action="restore" />
            </MelodyActionButton>
          )}
          <MelodyEditorPopover label="Export melody" icon="export">
            <MelodyExport key={melody.title} melody={melody} />
          </MelodyEditorPopover>
          <MelodyEditorPopover label="About this melody" icon="info">
            <Notice>
              Key: <strong>{tonality}</strong> · Scale:{' '}
              <strong>{capitalize(melody.scale)}</strong> · Mode:{' '}
              <strong>
                {microtonalPreset(melody.scale, melody.mode)?.label ??
                  capitalize(melody.mode)}
              </strong>
            </Notice>
            {melody.source && (
              <>
                <a href={melody.source.url} target="_blank" rel="noreferrer">
                  Score source: {melody.source.label}
                </a>
                <Notice>
                  {melody.source.section} {melody.source.adaptation}
                </Notice>
              </>
            )}
            <MelodyScaleOptimization melody={melody} onStop={stopPlayback} />
          </MelodyEditorPopover>
        </Actions>
      </Header>
      {librarySaveError && (
        <Notice role="alert">
          This browser could not save your edits. Reloading may discard them.
        </Notice>
      )}
      <RecordingEditor
        compact
        key={melody.title}
        melody={melody}
        onStop={stopPlayback}
        onPlay={playback.play}
        isPlaying={isPlaying}
        isPaused={playback.isPaused}
        isAudition={playback.isAudition}
        onPause={playback.pause}
        onResume={playback.resume}
        onSeek={playback.seek}
        position={playback.position}
        timelinePlaying={playback.timelinePlaying}
        onChange={(notes, bpm) => {
          batch(() => {
            dispatch(
              melodiesActions.editLibraryMelody({
                title: melody.title,
                notes,
                bpm,
              }),
            );
            dispatch(settingsActions.setBpm(bpm));
          });
        }}
      />
    </Workspace>
  );
};

const Workspace = styled(PageWrapper)`
  display: flex;
  flex-direction: column;
  gap: 8px;
  height: var(--app-content-height);
  padding: 12px 32px 32px;
  @media (max-width: 700px) {
    padding: 8px 12px 32px;
  }
`;
const Header = styled.div`
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  flex-shrink: 0;
  h1 {
    flex: 1;
    min-width: 0;
    margin: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    text-align: left;
    font-family: inherit;
    font-size: clamp(16px, 2vw, 22px);
    font-weight: 600;
  }
  @media (max-width: 600px) {
    h1 {
      flex-basis: calc(100% - 90px);
    }
  }
`;
const Actions = styled.div`
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 4px;
  max-width: 100%;
  margin-left: auto;
`;
const Saved = styled.span`
  color: ${p => p.theme.primary};
  font-size: 16px;
`;
const Notice = styled.p`
  margin: 8px 0;
  color: ${p => p.theme.textSecondary};
  font-size: 12px;
`;
