export const createGuitarDistortion = (audio: AudioContext): AudioNode => {
  const input = audio.createBiquadFilter();
  input.type = 'highpass';
  input.frequency.value = 80;
  input.Q.value = 0.7;

  const distortion = audio.createWaveShaper();
  const curve = new Float32Array(4097);
  for (let i = 0; i < curve.length; i++) {
    const sample = (i * 2) / (curve.length - 1) - 1;
    curve[i] = Math.tanh(sample * 25);
  }
  distortion.curve = curve;
  distortion.oversample = '4x';

  const cabinet = audio.createBiquadFilter();
  cabinet.type = 'lowpass';
  cabinet.frequency.value = 3500;
  cabinet.Q.value = 0.7;

  const volume = audio.createGain();
  volume.gain.value = 0.2;

  input.connect(distortion);
  distortion.connect(cabinet);
  cabinet.connect(volume);
  volume.connect(audio.destination);

  return input;
};
