import { useState } from 'react';
import styled from 'styled-components';

import { useGuitarInput } from 'app/services/GuitarInputService/useGuitarInput';

import { AudioOutputSelect } from './AudioOutputSelect';
import { InputSoundControls } from './InputSoundControls';
import { NoiseGateControls } from './NoiseGateControls';

export const EffectsRouting = ({
  guitar,
  live,
  onLiveChange,
  recording,
}: {
  guitar: ReturnType<typeof useGuitarInput>;
  live: boolean;
  onLiveChange: (value: boolean) => void;
  recording: boolean;
}) => {
  const [switching, setSwitching] = useState(false);
  const { playbackOutput } = guitar;
  const inputs = guitar.devices.filter(device => device.deviceId);

  return (
    <Routing aria-label="Audio routing">
      <Fields>
        <label>
          Input
          <select
            aria-label="Effects input source"
            value={live ? `audio:${guitar.deviceId}` : 'instrument'}
            disabled={recording || guitar.connecting}
            onChange={event => {
              const value = event.target.value;
              guitar.stopMonitoring();
              onLiveChange(value !== 'instrument');
              if (value !== 'instrument') {
                const id = value.slice('audio:'.length);
                if (!guitar.connected || id !== guitar.deviceId)
                  guitar.selectDevice(id);
              }
            }}
          >
            <option value="instrument">
              Melody Generator · keyboard / MIDI
            </option>
            {guitar.supported && (
              <>
                <option value="audio:">System audio input</option>
                {guitar.deviceId &&
                  !inputs.some(
                    device => device.deviceId === guitar.deviceId,
                  ) && (
                    <option value={`audio:${guitar.deviceId}`}>
                      Selected audio input
                    </option>
                  )}
                {inputs.map((device, index) => (
                  <option
                    key={device.deviceId}
                    value={`audio:${device.deviceId}`}
                  >
                    {device.label || `Audio input ${index + 1}`}
                  </option>
                ))}
              </>
            )}
          </select>
        </label>
        {live && guitar.connected && guitar.channels > 1 && (
          <label>
            Channel
            <select
              aria-label="Effects input channel"
              value={guitar.channel}
              disabled={recording}
              onChange={event =>
                guitar.selectChannel(Number(event.target.value))
              }
            >
              {Array.from({ length: guitar.channels }, (_, channel) => (
                <option key={channel} value={channel}>
                  Input {channel + 1}
                </option>
              ))}
            </select>
          </label>
        )}
        <AudioOutputSelect
          label="App audio output"
          devices={guitar.outputs}
          deviceId={playbackOutput.deviceId}
          disabled={!playbackOutput.supported || playbackOutput.switching}
          onChange={playbackOutput.selectDevice}
        />
        {live && (
          <AudioOutputSelect
            label="Live sound output"
            devices={guitar.outputs}
            deviceId={guitar.connected ? guitar.outputDeviceId : ''}
            disabled={!guitar.canSelectOutput || !guitar.connected || switching}
            onChange={async id => {
              setSwitching(true);
              await guitar.selectOutput(id);
              setSwitching(false);
            }}
          />
        )}
        <button
          type="button"
          disabled={
            !guitar.supported ||
            guitar.requestingDevices ||
            guitar.connecting ||
            recording
          }
          title="Allow microphone access to see all available inputs and outputs. This does not enable sound."
          onClick={guitar.requestDevices}
        >
          {guitar.requestingDevices ? 'Finding devices…' : 'Refresh devices'}
        </button>
      </Fields>
      {(!playbackOutput.supported ||
        (live && guitar.connected && !guitar.canSelectOutput)) && (
        <Hint>Select audio output in your system or browser settings.</Hint>
      )}
      {!guitar.supported && (
        <Hint>Audio input is unavailable in this browser.</Hint>
      )}
      {live && (
        <LiveControls>
          {guitar.connecting ? (
            <button type="button" onClick={guitar.disconnect}>
              Cancel connection
            </button>
          ) : guitar.connected ? (
            <>
              <button
                type="button"
                aria-pressed={guitar.monitoring}
                onClick={
                  guitar.monitoring
                    ? guitar.stopMonitoring
                    : guitar.startMonitoring
                }
              >
                {guitar.monitoring
                  ? 'Turn off live sound'
                  : 'Turn on live sound'}
              </button>
              <button type="button" onClick={guitar.disconnect}>
                Disconnect input
              </button>
            </>
          ) : (
            <button
              type="button"
              disabled={recording}
              onClick={() => guitar.connect()}
            >
              Connect audio input
            </button>
          )}
          <span role="status">
            {guitar.connecting
              ? guitar.connectionStatus
              : guitar.monitoring
              ? 'Live sound is on'
              : 'Live sound is off'}
          </span>
          <Hint>
            Use headphones to avoid feedback. If you change the input channel or
            live sound output, turn live sound back on. The compressor adds
            delay.
          </Hint>
        </LiveControls>
      )}
      {live && <InputSoundControls guitar={guitar} />}
      {live && (guitar.inputSound ?? 'effects') === 'effects' && (
        <NoiseGateControls
          settings={guitar.noiseGate}
          onChange={guitar.updateNoiseGate}
        />
      )}
      {guitar.error && <Hint role="alert">{guitar.error}</Hint>}
      {playbackOutput.error && <Hint role="alert">{playbackOutput.error}</Hint>}
    </Routing>
  );
};

const Routing = styled.section`
  margin-bottom: 16px;
  padding: 12px;
  border: 1px solid ${p => p.theme.border};
  border-radius: 8px;
  background: ${p => p.theme.background};
  font-size: 12px;
  button,
  select {
    min-height: 36px;
    font: inherit;
  }
  select {
    width: 100%;
    min-width: 0;
  }
`;

const Fields = styled.div`
  display: flex;
  flex-wrap: wrap;
  align-items: end;
  gap: 12px;
  label {
    display: flex;
    flex: 1 1 200px;
    min-width: 0;
    flex-direction: column;
    gap: 6px;
    color: ${p => p.theme.textSecondary};
  }
  @media (max-width: 480px) {
    label {
      flex-basis: 100%;
    }
    button {
      width: 100%;
    }
  }
`;

const LiveControls = styled.div`
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  margin-top: 12px;
  [aria-pressed='true'] {
    color: ${p => p.theme.primary};
    border-color: currentColor;
  }
`;

const Hint = styled.p`
  flex-basis: 100%;
  margin: 8px 0 0;
  color: ${p => p.theme.textSecondary};
  line-height: 1.5;
  &[role='alert'] {
    color: ${p => p.theme.danger};
  }
`;
