import { chromaticNotes } from 'app/services/NotesService/chromaticNotes';
import { Note } from 'app/services/NotesService/types';

import { Melody, MelodySource } from '../types';

type PublishedScore = {
  source: Omit<MelodySource, 'extent'> & { extent: string };
  // Sounding MIDI pitch, onset in ms, notated duration in ms.
  events: number[][];
};

export const fromPublishedScore = (
  settings: Omit<Melody, 'notes' | 'source'>,
  score: PublishedScore,
): Melody => ({
  ...settings,
  source: {
    ...score.source,
    extent: score.source.extent === 'full' ? 'full' : 'excerpt',
  },
  notes: score.events.map(([pitch, start, duration]) => ({
    note: `${chromaticNotes[pitch % 12]}${Math.floor(pitch / 12) - 1}` as Note,
    start,
    duration,
  })),
});
