import { pitchAt } from '../MelodiesService/expression';
import { getTimeSignature } from '../MelodiesService/meter';
import { DEFAULT_BPM } from '../MelodiesService/timing';
import type { Melody } from '../MelodiesService/types';
import { MelodyExportError } from './errors';
import { getExportNotes } from './notes';

const PPQ = 960;
const variableLength = (value: number): number[] => {
  if (!Number.isSafeInteger(value) || value < 0 || value > 0x0fffffff) {
    throw new MelodyExportError('The melody is too long for a MIDI file.');
  }
  const bytes = [value & 0x7f];
  while ((value = Math.floor(value / 128)))
    bytes.unshift((value & 0x7f) | 0x80);
  return bytes;
};

const programFor = (timbre: string) => {
  const name = timbre.toLowerCase();
  if (name === 'oud') return 24;
  if (name === 'ney') return 73;
  if (name === 'banjo') return 105;
  // Use steel-string guitar for plucked instruments outside General MIDI.
  if (name === 'mandolin' || name === 'balalaika') return 25;
  // General MIDI has no Hang; use the closest pitched steel percussion.
  if (name === 'hang') return 114;
  if (/distort|tele/.test(name)) return 30;
  if (/guitar|acclassy|acousticsteel|ac12|acdark|acclean/.test(name)) return 25;
  if (/bass/.test(name)) return 33;
  if (/accordion/.test(name)) return 21;
  if (/organ/.test(name)) return 19;
  if (/cello/.test(name)) return 42;
  if (/strings/.test(name)) return 48;
  if (/horn/.test(name)) return 60;
  if (/harpsichord/.test(name)) return 6;
  if (/celeste/.test(name)) return 8;
  if (/electric|epiano/.test(name)) return 4;
  if (/8bit|sine|sawtooth|square|triangle/.test(name)) return 80;
  return 0;
};

export const encodeMidi = (melody: Melody): Uint8Array => {
  const notes = getExportNotes(melody);
  const bpm =
    Number.isFinite(melody.bpm) && melody.bpm! > 0 ? melody.bpm! : DEFAULT_BPM;
  const tempo = Math.max(1, Math.min(0xffffff, Math.round(60000000 / bpm)));
  const ticks = (ms: number) => Math.round((ms * 1000 * PPQ) / tempo);
  const [numerator, denominator] = getTimeSignature(melody.timeSignature)
    .split('/')
    .map(Number);
  const channel = melody.timbre === 'drums' ? 9 : 0;
  const title = new TextEncoder().encode(
    melody.displayTitle || melody.title || 'Recording',
  );
  const track: number[] = [
    0,
    0xff,
    0x03,
    ...variableLength(title.length),
    ...Array.from(title),
    0,
    0xff,
    0x51,
    3,
    (tempo >> 16) & 255,
    (tempo >> 8) & 255,
    tempo & 255,
    0,
    0xff,
    0x58,
    4,
    numerator,
    Math.log2(denominator),
    24,
    8,
    0,
    0xc0 | channel,
    programFor(melody.timbre),
  ];
  const events: { tick: number; priority: number; bytes: number[] }[] = [];
  const channelEnds = Array(16).fill(-Infinity);
  const add = (tick: number, priority: number, ...bytes: number[]) =>
    events.push({ tick, priority, bytes });
  notes.forEach(note => {
    const start = ticks(note.start);
    const end = Math.max(start + 1, ticks(note.end));
    const pitch = note.pitch - (channel === 9 ? 12 : 0);
    let voiceChannel = channel;
    if (note.expression && channel !== 9) {
      voiceChannel = channelEnds.findIndex(
        (until, index) => index !== 0 && index !== 9 && until <= start,
      );
      if (voiceChannel < 0)
        throw new MelodyExportError(
          'MIDI supports up to 14 simultaneous notes with independent pitch bends. Choose WAV or MP3 for this recording.',
        );
      channelEnds[voiceChannel] = end;
      const range = Math.max(
        2,
        Math.ceil(
          Math.max(...note.expression.points.map(p => Math.abs(p.cents))) / 100,
        ),
      );
      add(start, 2, 0xc0 | voiceChannel, programFor(melody.timbre));
      [
        [101, 0],
        [100, 0],
        [6, range],
        [38, 0],
        [101, 127],
        [100, 127],
      ].forEach(([cc, value]) => add(start, 2, 0xb0 | voiceChannel, cc, value));
      const steps = Math.max(1, Math.ceil((note.end - note.start) / 20));
      const positions = Array.from(
        new Set([
          ...note.expression.points.map(p => p.position),
          ...Array.from({ length: steps + 1 }, (_, i) => i / steps),
        ]),
      ).sort((a, b) => a - b);
      positions.forEach(position => {
        const wheel = Math.max(
          0,
          Math.min(
            16383,
            Math.round(
              8192 +
                (pitchAt(note.expression!.points, position) / (range * 100)) *
                  8192,
            ),
          ),
        );
        add(
          Math.min(end - 1, start + Math.round((end - start) * position)),
          3,
          0xe0 | voiceChannel,
          wheel & 127,
          (wheel >> 7) & 127,
        );
      });
      add(end, 1, 0xe0 | voiceChannel, 0, 64);
    }
    add(start, 4, 0x90 | voiceChannel, pitch, 100);
    add(end, 0, 0x80 | voiceChannel, pitch, 0);
  });
  events.sort((a, b) => a.tick - b.tick || a.priority - b.priority);
  let previousTick = 0;
  events.forEach(({ tick, bytes }) => {
    track.push(...variableLength(tick - previousTick), ...bytes);
    previousTick = tick;
  });
  track.push(0, 0xff, 0x2f, 0);
  const file = new Uint8Array(22 + track.length);
  file.set([
    0x4d,
    0x54,
    0x68,
    0x64,
    0,
    0,
    0,
    6,
    0,
    0,
    0,
    1,
    PPQ >> 8,
    PPQ & 255,
  ]);
  file.set([0x4d, 0x54, 0x72, 0x6b], 14);
  new DataView(file.buffer).setUint32(18, track.length);
  file.set(track, 22);
  return file;
};
