import type { useGuitarInput } from 'app/services/GuitarInputService/useGuitarInput';

export const InputSoundControls = ({
  guitar,
}: {
  guitar: Pick<
    ReturnType<typeof useGuitarInput>,
    | 'inputSound'
    | 'inputPolyphonic'
    | 'setInputSound'
    | 'setInputPolyphonic'
    | 'inputTransferAmount'
    | 'setInputTransferAmount'
    | 'transferDelayMs'
  >;
}) => (
  <div>
    <label>
      Audio input sound
      <select
        aria-label="Audio input sound"
        value={guitar.inputSound ?? 'effects'}
        onChange={event =>
          guitar.setInputSound(event.target.value as typeof guitar.inputSound)
        }
      >
        <option value="effects">Original sound with effects</option>
        <option value="instrument">Selected app instrument</option>
        <option value="transfer">Instrument loop: bends and dynamics</option>
      </select>
    </label>
    {guitar.inputSound === 'instrument' && (
      <>
        <label>
          Instrument playback
          <select
            aria-label="Recognition for selected instrument"
            value={guitar.inputPolyphonic ? 'poly' : 'mono'}
            onChange={event =>
              guitar.setInputPolyphonic(event.target.value === 'poly')
            }
          >
            <option value="mono">Single note: faster</option>
            <option value="poly">Notes and chords</option>
          </select>
        </label>
        <p>
          Choose a piano or another instrument in the toolbar and turn on live
          sound. You can play without recording. The selected instrument
          supplies volume and effects; the original input is muted.
        </p>
        <p>
          Recognition adds latency. Clean single notes respond faster; chords
          take longer and may be misidentified. Use headphones to prevent app
          sound from feeding back into the microphone.
        </p>
      </>
    )}
    {guitar.inputSound === 'transfer' && (
      <>
        <label>
          Loop mix: {guitar.inputTransferAmount}%
          <input
            type="range"
            aria-label="Instrument loop mix"
            min={0}
            max={100}
            step={1}
            value={guitar.inputTransferAmount}
            onChange={event =>
              guitar.setInputTransferAmount(Number(event.target.value))
            }
          />
        </label>
        <p>
          A steady section of the selected sample loops without decay. Input
          volume controls its envelope, and continuous pitch controls loop
          speed: bends and vibrato without rounding to notes. Pitch changes do
          not restart the loop.
        </p>
        <p>
          Single notes only: chords are not separated. At 100% you hear the
          loop; at 0%, the original input; in between, a mix. A steady pitched
          sample is required; noise and some percussion may not produce a loop.
          Analysis window: {guitar.transferDelayMs} ms, updated every 10 ms;
          total latency depends on the input and device. Use headphones.
        </p>
      </>
    )}
  </div>
);
