import { makeExpression } from 'app/services/MelodiesService/expression';
import { clampTempo } from 'app/services/MelodiesService/tempo';
import { DEFAULT_BPM } from 'app/services/MelodiesService/timing';
import type { NoteExpression } from 'app/services/MelodiesService/types';

import { readPreferences, writePreferences } from 'utils/preferences';

import { MAX_FRET } from './fingering';
import { STRINGS } from './tuning';

export type GuitarTuning = 'guitar' | 'guitarDropD';
export type TabNote = {
  fret: number;
  slide?: number;
  bend?: number;
  vibrato?: boolean;
  duration?: number; // Measured sounding time in milliseconds.
  expression?: NoteExpression;
};
export type TabStep = (TabNote | null)[];
export type TabDraft = { tuning: GuitarTuning; bpm: number; steps: TabStep[] };
export type TabCursor = { step: number; string: number };
export type TabEditor = {
  draft: TabDraft;
  cursor: TabCursor;
  attack?: { id: number; cell?: TabCursor };
};

const DRAFT_KEY = 'qwertophone.tab-creator.v1';
const STRING_COUNT = STRINGS.guitar.length;
const INITIAL_STEPS = 8;

export const emptyStep = (): TabStep => Array(STRING_COUNT).fill(null);
const blankSteps = () => Array.from({ length: INITIAL_STEPS }, emptyStep);

export const clearTab = (draft: TabDraft): TabEditor => ({
  draft: { ...draft, steps: blankSteps() },
  cursor: { step: 0, string: 0 },
});

export const parseFret = (value: string) => {
  if (!/^\d{1,2}$/.test(value)) return null;
  const fret = Number(value);
  return fret <= MAX_FRET ? fret : null;
};

const isFret = (value: unknown): value is number =>
  typeof value === 'number' &&
  Number.isInteger(value) &&
  value >= 0 &&
  value <= MAX_FRET;

const readNote = (value: unknown): TabNote | null => {
  if (!value || typeof value !== 'object') return null;
  const { fret, slide, bend, vibrato, duration, expression } =
    value as Partial<TabNote>;
  if (!isFret(fret)) return null;
  const curve =
    expression && Array.isArray(expression.points)
      ? makeExpression(
          expression.points.filter(
            point =>
              Number.isFinite(point?.position) && Number.isFinite(point?.cents),
          ),
          Array.isArray(expression.techniques)
            ? expression.techniques.filter(
                technique =>
                  technique === 'bend' ||
                  technique === 'slide' ||
                  technique === 'vibrato' ||
                  technique === 'wide-vibrato',
              )
            : undefined,
        )
      : undefined;
  return {
    fret,
    ...(isFret(slide) && slide !== fret
      ? { slide }
      : bend === 1 || bend === 2 || bend === 3
      ? { bend }
      : {}),
    ...(vibrato === true ? { vibrato } : {}),
    ...(typeof duration === 'number' &&
    Number.isFinite(duration) &&
    duration > 0
      ? { duration }
      : {}),
    ...(curve ? { expression: curve } : {}),
  };
};

export const loadTabDraft = (): TabDraft => {
  const { tuning, bpm, steps } = readPreferences(DRAFT_KEY);
  if (
    (tuning === 'guitar' || tuning === 'guitarDropD') &&
    Array.isArray(steps) &&
    steps.length > 0
  ) {
    return {
      tuning,
      bpm:
        typeof bpm === 'number' && Number.isFinite(bpm)
          ? clampTempo(bpm)
          : DEFAULT_BPM,
      steps: steps.map(step =>
        Array.isArray(step)
          ? Array.from({ length: STRING_COUNT }, (_, string) =>
              readNote(step[string]),
            )
          : emptyStep(),
      ),
    };
  }
  return {
    tuning: 'guitar',
    bpm: DEFAULT_BPM,
    steps: blankSteps(),
  };
};

export const saveTabDraft = (draft: TabDraft) =>
  writePreferences(DRAFT_KEY, draft);

export const writeTabNote = (
  draft: TabDraft,
  { step, string }: TabCursor,
  note: TabNote | null,
): TabDraft => {
  const steps = [...draft.steps];
  steps[step] = [...steps[step]];
  steps[step][string] = note;
  return { ...draft, steps };
};

export const techniqueMark = ({ fret, slide, bend, vibrato }: TabNote) => {
  const gesture =
    slide !== undefined
      ? `${slide > fret ? '/' : '\\'}${slide}`
      : bend
      ? `b${fret + bend}`
      : '';
  return `${gesture}${vibrato ? '~' : ''}`;
};
