import { useCallback, useEffect, useRef, useState } from 'react';

import { loadSound, resumeAudio } from 'app/services/SynthesizerService';

import { PlaybackMelody } from './types';
import { useMelodyPlayback } from './useMelodyPlayback';

export const useLibraryPlayback = ({ loop = false } = {}) => {
  const {
    playPreview,
    seekPreview,
    stop: stopPlayback,
    isPlaying,
    position,
  } = useMelodyPlayback(undefined, undefined, { loopPreview: loop });
  const [title, setTitle] = useState<string>();
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const request = useRef(0);
  const [pendingPosition, setPendingPosition] = useState<number>();
  const pendingSeek = useRef<number>();
  const movePendingPosition = useCallback((time?: number) => {
    pendingSeek.current = time;
    setPendingPosition(time);
  }, []);

  const stop = useCallback(() => {
    request.current++;
    stopPlayback();
    setTitle(undefined);
    setLoading(false);
    movePendingPosition();
  }, [movePendingPosition, stopPlayback]);

  const start = async (melody: PlaybackMelody, time = 0) => {
    stop();
    setError('');
    if (!melody.notes.length) return;
    const version = request.current;
    movePendingPosition(time);
    setTitle(melody.title);
    setLoading(true);
    try {
      // Unlock audio in the click handler, then wait for this instrument's sample.
      const timbres = new Set(
        melody.notes.map(note => note.timbre ?? melody.timbre),
      );
      await Promise.all([
        resumeAudio(),
        ...Array.from(timbres, timbre => loadSound(timbre)),
      ]);
      if (request.current !== version) return;
      setLoading(false);
      playPreview(melody, pendingSeek.current ?? 0);
      movePendingPosition();
    } catch {
      if (request.current !== version) return;
      stop();
      setError('Could not start the melody. Try again.');
    }
  };

  const toggle = async (melody: PlaybackMelody) => {
    if (title === melody.title && (isPlaying || loading)) stop();
    else await start(melody, pendingSeek.current);
  };
  const seek = (time: number) => {
    if (isPlaying) seekPreview(time);
    else movePendingPosition(time);
  };

  useEffect(
    () => () => {
      request.current++;
    },
    [],
  );

  return {
    activeTitle: isPlaying || loading ? title : undefined,
    loading,
    isPlaying,
    position: pendingPosition ?? position,
    error,
    start,
    toggle,
    seek,
    stop,
  };
};
