import { useState } from 'react';
import { Helmet } from 'react-helmet-async';
import { useSearchParams } from 'react-router-dom';
import styled from 'styled-components';

import { guitarExercises } from 'app/services/PlayAlongService/guitarExercises';

import { PlayAlongSession } from './PlayAlongPage';

export const GuitarPracticeRoutinePage = () => {
  const [params, setParams] = useSearchParams();
  const exercise =
    guitarExercises.find(
      ({ melody }) => melody.title === params.get('exercise'),
    ) ?? guitarExercises[0];
  const [player, setPlayer] = useState<'tabs' | 'guitar'>('tabs');
  const [speed, setSpeed] = useState(1);
  const [guideSound, setGuideSound] = useState(true);
  const { melody, tip } = exercise;

  return (
    <PlayAlongSession
      melody={melody}
      source={{
        type: 'routine',
        player,
        speed,
        onSpeed: setSpeed,
        guideSound,
        onGuideSound: setGuideSound,
        intro: (
          <Intro>
            <Helmet title="Guitar Practice Routine" />
            <h1>Guitar Practice Routine</h1>
            <p>Standard tuning · E A D G B E · Two passes per exercise</p>
            <Options>
              <label>
                Exercise
                <select
                  value={melody.title}
                  onChange={event =>
                    setParams({ exercise: event.target.value })
                  }
                >
                  {guitarExercises.map(({ melody }, index) => (
                    <option key={melody.title} value={melody.title}>
                      {index + 1}. {melody.displayTitle}
                    </option>
                  ))}
                </select>
              </label>
              <ModePicker role="group" aria-label="Play with">
                <button
                  type="button"
                  aria-pressed={player === 'tabs'}
                  onClick={() => setPlayer('tabs')}
                >
                  Tab player
                </button>
                <button
                  type="button"
                  aria-pressed={player === 'guitar'}
                  onClick={() => setPlayer('guitar')}
                >
                  Guitar input
                </button>
              </ModePicker>
            </Options>
            <p>{tip}</p>
            <p>
              {player === 'tabs'
                ? 'Follow the scrolling tabs. No microphone needed.'
                : 'Connect a microphone or audio interface to get feedback on each note.'}
            </p>
          </Intro>
        ),
      }}
    />
  );
};

const Intro = styled.section`
  display: grid;
  gap: 8px;
  padding: 12px;
  border: 1px solid ${p => p.theme.border};
  border-radius: 10px;
  background: ${p => p.theme.surface};

  h1 {
    margin: 0;
    font-size: clamp(20px, 4vw, 28px);
    line-height: 1.2;
  }
  p {
    margin: 0;
    font-size: 13px;
    color: ${p => p.theme.textSecondary};
  }
`;

const Options = styled.div`
  display: flex;
  flex-wrap: wrap;
  align-items: end;
  gap: 8px 16px;

  label {
    display: grid;
    flex: 0 1 230px;
    min-width: 0;
    gap: 4px;
    font-size: 12px;
  }
  select,
  button {
    min-width: 0;
    min-height: 36px;
    padding: 4px 10px;
    border: 1px solid ${p => p.theme.border};
    border-radius: 6px;
    background: ${p => p.theme.background};
    color: ${p => p.theme.text};
    font-size: 13px;

    @media (pointer: coarse) {
      min-height: 44px;
    }
  }
`;

const ModePicker = styled.div`
  display: flex;
  flex-wrap: wrap;
  gap: 4px;

  button[aria-pressed='true'] {
    border-color: ${p => p.theme.primary};
    box-shadow: inset 0 -2px ${p => p.theme.primary};
  }
`;
