export const AudioOutputSelect = ({
  label,
  devices,
  deviceId,
  disabled,
  onChange,
}: {
  label: string;
  devices: MediaDeviceInfo[];
  deviceId: string;
  disabled: boolean;
  onChange: (id: string) => void;
}) => {
  const outputs = devices.filter(
    device => device.deviceId && device.deviceId !== 'default',
  );
  return (
    <label>
      {label}
      <select
        value={deviceId}
        disabled={disabled}
        onChange={event => onChange(event.target.value)}
      >
        <option value="">System output</option>
        {deviceId && !outputs.some(device => device.deviceId === deviceId) && (
          <option value={deviceId}>Selected audio output</option>
        )}
        {outputs.map((device, index) => (
          <option key={device.deviceId} value={device.deviceId}>
            {device.label || `Audio output ${index + 1}`}
          </option>
        ))}
      </select>
    </label>
  );
};
