import { chromaticNotes } from 'app/services/NotesService/chromaticNotes';
import { Note } from 'app/services/NotesService/types';

type NoteMessage = {
  type: 'noteOn' | 'noteOff';
  channel: number;
  number: number;
  note: Note;
};
type ControllerMessage = {
  type: 'sustain' | 'resetControllers' | 'allNotesOff';
  channel: number;
  down: boolean;
};

export const parseMidiMessage = (
  data: Uint8Array,
): NoteMessage | ControllerMessage | undefined => {
  if (data.length !== 3) return;
  const status = data[0];
  const number = data[1];
  const value = data[2];
  if (number > 127 || value > 127) return;
  const command = status & 0xf0;
  const channel = status & 0x0f;
  if (command === 0xb0) {
    if (number === 64) return { type: 'sustain', channel, down: value >= 64 };
    if (number === 120 || number === 123)
      return { type: 'allNotesOff', channel, down: false };
    if (number === 121)
      return { type: 'resetControllers', channel, down: false };
    return;
  }
  if (command !== 0x80 && command !== 0x90) return;
  // Melody Generator supports C0 through B8, including the full 88-key piano range.
  if (number < 12 || number > 119) return;
  const note = `${chromaticNotes[number % 12]}${
    Math.floor(number / 12) - 1
  }` as Note;
  return {
    type: command === 0x90 && value > 0 ? 'noteOn' : 'noteOff',
    channel,
    number,
    note,
  };
};
