import { useId } from 'react';
import styled from 'styled-components';

import { DemoHint, DemoPanel } from './LandingDemoStyles';
import { Fretboard } from './VirtualGuitar/Fretboard';
import { Board, BoardPanel, Cell, Neck } from './VirtualGuitar/styles';

export const LandingGuitar = ({ visible }: { visible: boolean }) => {
  const hintId = useId();
  return (
    <DemoPanel role="group" aria-label="Guitar" aria-describedby={hintId}>
      <EmbeddedFretboard
        enabled={visible}
        lastFret={7}
        showFeedback={false}
        showOpenNotes={false}
        hint={
          <DemoHint id={hintId}>
            Hold a fret. Drag sideways to slide, vertically to bend, or
            diagonally to do both.
          </DemoHint>
        }
      />
    </DemoPanel>
  );
};

const EmbeddedFretboard = styled(Fretboard)`
  flex: 1;
  grid-template-rows: auto 1fr;

  & ${BoardPanel}, & ${Neck} {
    display: flex;
    flex-direction: column;
  }

  & ${Neck}, & ${Board} {
    flex: 1;
  }

  & ${Board} {
    grid-auto-rows: minmax(32px, 1fr);
  }

  & ${Cell} {
    min-height: 32px;
  }
`;
