import { useEffect, useId, useRef, useState } from 'react';
import styled from 'styled-components';

import { InstrumentEffects } from 'app/services/EffectsService/settings';
import { useConnectedGuitarInput } from 'app/services/GuitarInputService/context';

import { EffectsDialog, EffectsDialogElement } from '../EffectsDialog';
import { GuitarInput } from '../GuitarInput';

export const ExternalGuitar = ({
  effects,
  onVolumeChange,
}: {
  effects: InstrumentEffects;
  onVolumeChange: (volume: number) => void;
}) => {
  const guitar = useConnectedGuitarInput();
  const { monitoringVirtualGuitar, updateVirtualGuitarMonitoring } = guitar;
  const [open, setOpen] = useState(false);
  const id = useId();
  const dialog = useRef<EffectsDialogElement>(null);
  const trigger = useRef<HTMLButtonElement>(null);

  useEffect(() => {
    updateVirtualGuitarMonitoring(effects);
  }, [effects, updateVirtualGuitarMonitoring]);

  useEffect(
    () => () => updateVirtualGuitarMonitoring(),
    [updateVirtualGuitarMonitoring],
  );

  return (
    <>
      <Trigger
        ref={trigger}
        type="button"
        aria-haspopup="dialog"
        aria-controls={id}
        data-active={monitoringVirtualGuitar}
        onClick={() => {
          dialog.current?.showModal();
          setOpen(true);
        }}
      >
        Guitar input
      </Trigger>
      <EffectsDialog
        id={id}
        ref={dialog}
        $width={560}
        aria-labelledby={`${id}-title`}
        onClose={() => {
          setOpen(false);
          trigger.current?.focus();
        }}
      >
        <Header>
          <h2 id={`${id}-title`}>Guitar input</h2>
          <button type="button" onClick={() => dialog.current?.close()}>
            Done
          </button>
        </Header>
        <GuitarInput
          open={open}
          guitar={guitar}
          virtualGuitarEffects={effects}
        />
        {open && guitar.connected && (
          <Volume>
            <span>Output volume</span>
            <input
              type="range"
              min={0}
              max={100}
              value={effects.volume}
              aria-valuetext={`${effects.volume}%`}
              onChange={event => onVolumeChange(Number(event.target.value))}
            />
            <span aria-hidden="true">{effects.volume}%</span>
          </Volume>
        )}
      </EffectsDialog>
    </>
  );
};

const Trigger = styled.button`
  flex: none;
  padding-inline: 10px;
  font-size: 12px;

  &[data-active='true'] {
    border-color: ${p => p.theme.primary};
    color: ${p => p.theme.primary};
  }

  @media (max-height: 470px) {
    min-height: 34px;
    padding-block: 4px;
  }
`;

const Header = styled.div`
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
`;

const Volume = styled.label`
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 12px;
  font-size: 12px;

  input {
    flex: 1;
    min-width: 0;
  }
`;
