import { DEFAULT_BPM, getNoteDuration } from './timing';
import { Melody } from './types';

export type Subdivision = 0 | 1 | 2 | 3 | 4 | 8;

export interface NormalizationOptions {
  bpm: number;
  /** Divisions per quarter note; zero leaves timing unchanged. */
  subdivision: Subdivision;
  quantizeDurations: boolean;
  quantizeStarts?: boolean;
  removeShortNotes: boolean;
  minDurationMs: number;
}

export const getNormalizationOptions = (
  melody: Melody,
): NormalizationOptions => ({
  bpm:
    melody.bpm && Number.isFinite(melody.bpm) && melody.bpm > 0
      ? melody.bpm
      : DEFAULT_BPM,
  subdivision: 4,
  quantizeDurations: true,
  quantizeStarts: true,
  removeShortNotes: false,
  minDurationMs: 40,
});

/** Pure, opt-in editing. Playback itself always uses the recorded timing. */
export const normalizeMelody = (
  melody: Melody,
  options: NormalizationOptions,
) => {
  const bpm = Number.isFinite(options.bpm)
    ? Math.max(40, Math.min(220, options.bpm))
    : getNormalizationOptions(melody).bpm;
  const step = options.subdivision ? 60000 / bpm / options.subdivision : 0;
  // Round only at the output boundary, so triplets and fractional BPM grids
  // do not accumulate timing drift. Half-grid ties round forward.
  const snap = (time: number) =>
    step ? Math.round(Math.round(time / step) * step) : time;
  const threshold = Number.isFinite(options.minDurationMs)
    ? Math.max(1, Math.min(250, options.minDurationMs))
    : 40;
  if (options.quantizeStarts === false) {
    const events = melody.notes
      .filter(
        note => !options.removeShortNotes || getNoteDuration(note) >= threshold,
      )
      .map(original => ({
        original,
        note: {
          ...original,
          duration:
            step && options.quantizeDurations
              ? Math.max(Math.round(step), snap(getNoteDuration(original)))
              : getNoteDuration(original),
        },
      }));
    const notes = events.map(event => event.note);
    events.forEach(({ note, original }) => {
      const next = notes
        .filter(
          event =>
            event.start > note.start &&
            original.start + getNoteDuration(original) <= event.start,
        )
        .sort((a, b) => a.start - b.start)[0];
      if (next)
        note.duration = Math.max(
          1,
          Math.min(note.duration, next.start - note.start),
        );
    });
    return {
      melody: { ...melody, bpm, notes },
      changedNotes: events.filter(
        ({ original, note }) => original.duration !== note.duration,
      ).length,
      removedNotes: melody.notes.length - notes.length,
      preservedNotes: 0,
    };
  }
  const events = melody.notes
    .filter(
      note => !options.removeShortNotes || getNoteDuration(note) >= threshold,
    )
    .map(original => ({
      original,
      note: {
        ...original,
        start: snap(original.start),
        duration: getNoteDuration(original),
      },
    }))
    .sort((a, b) => a.original.start - b.original.start);

  // Chord attacks within 50 ms share the first attack's grid position. Require
  // actual overlap, so a short run crossing a grid midpoint stays a run.
  let chord: typeof events = [];
  if (step) {
    events.forEach(event => {
      if (
        !chord.length ||
        event.original.start - chord[0].original.start >= 50 ||
        chord.some(
          ({ original }) =>
            original.note === event.original.note ||
            original.start + getNoteDuration(original) <= event.original.start,
        )
      ) {
        chord = [];
      }
      chord.push(event);
      event.note.start = snap(chord[0].original.start);
    });
  }

  const groups = new Map<number, typeof events>();
  events.forEach(event => {
    const group = groups.get(event.note.start) ?? [];
    group.push(event);
    groups.set(event.note.start, group);
  });

  const preserved = new Set<typeof events[number]>();
  groups.forEach(group => {
    const repeatedPitch =
      new Set(group.map(({ note }) => note.note)).size < group.length;
    // [start, end): a release exactly at the next attack is a separate note.
    // A coarse grid must not turn a fast run or repeated attacks into a chord.
    const separateAttacks =
      Math.min(
        ...group.map(
          ({ original }) => original.start + getNoteDuration(original),
        ),
      ) <= Math.max(...group.map(({ original }) => original.start));
    const preserve = !!step && (repeatedPitch || separateAttacks);
    group.forEach(event => {
      if (preserve) {
        event.note.start = event.original.start;
        preserved.add(event);
      } else if (step && options.quantizeDurations) {
        event.note.duration =
          Math.max(
            snap(event.original.start + getNoteDuration(event.original)),
            snap(event.note.start + step),
          ) - event.note.start;
      }
    });
  });

  // Keep an existing gap/release before a repeated pitch. Intentional overlaps
  // of different voices and independent chord durations remain independent.
  const eventsByPitch = new Map<string, typeof events>();
  events.forEach(event => {
    const voice = eventsByPitch.get(event.note.note) ?? [];
    voice.push(event);
    eventsByPitch.set(event.note.note, voice);
  });
  eventsByPitch.forEach(voice => {
    for (let i = 1; i < voice.length; i++) {
      const previous = voice[i - 1];
      const event = voice[i];
      if (
        previous.original.start + getNoteDuration(previous.original) <=
          event.original.start &&
        previous.note.start + previous.note.duration > event.note.start
      ) {
        if (
          !options.quantizeDurations ||
          preserved.has(previous) ||
          preserved.has(event)
        ) {
          // Preserve this pitch's sequence rather than shorten held notes when
          // duration editing is disabled or a fast sequence was protected.
          voice.forEach(item => {
            item.note.start = item.original.start;
            item.note.duration = getNoteDuration(item.original);
            preserved.add(item);
          });
          break;
        }
        previous.note.duration = Math.max(
          1,
          event.note.start - previous.note.start,
        );
      }
    }
  });

  return {
    melody: {
      ...melody,
      bpm,
      notes: events.map(({ note }) => note).sort((a, b) => a.start - b.start),
    },
    changedNotes: events.filter(
      ({ original, note }) =>
        original.start !== note.start || original.duration !== note.duration,
    ).length,
    removedNotes: melody.notes.length - events.length,
    preservedNotes: preserved.size,
  };
};
