import { melodies } from './melodies/melodies';
import { Melody, NoteInMelody } from './types';

export const LIBRARY_EDITS_KEY = 'qwertophone.melodyEdits.v1';
export type LibraryEdits = Record<
  string,
  NoteInMelody[] | Pick<Melody, 'notes' | 'bpm'>
>;

const isNote = (value: unknown): value is NoteInMelody => {
  if (!value || typeof value !== 'object') return false;
  const event = value as NoteInMelody;
  return (
    typeof event.note === 'string' &&
    /^[A-G]#?[0-8]$/.test(event.note) &&
    !/^[BE]#/.test(event.note) &&
    Number.isFinite(event.start) &&
    event.start >= 0 &&
    (event.duration === undefined || Number.isFinite(event.duration))
  );
};

export const readLibraryEdits = (): LibraryEdits => {
  try {
    const saved = JSON.parse(localStorage.getItem(LIBRARY_EDITS_KEY) ?? '{}');
    if (!saved || typeof saved !== 'object' || Array.isArray(saved)) return {};
    return Object.fromEntries(
      melodies.flatMap(({ title }) => {
        const value = saved[title];
        const notes = Array.isArray(value) ? value : value?.notes;
        const validTempo =
          Array.isArray(value) ||
          value?.bpm === undefined ||
          (Number.isFinite(value.bpm) && value.bpm >= 40 && value.bpm <= 220);
        return validTempo && Array.isArray(notes) && notes.every(isNote)
          ? [[title, Array.isArray(value) ? notes : { notes, bpm: value.bpm }]]
          : [];
      }),
    );
  } catch {
    return {};
  }
};

export const saveLibraryEdits = (edits: LibraryEdits): boolean => {
  try {
    if (Object.keys(edits).length) {
      localStorage.setItem(LIBRARY_EDITS_KEY, JSON.stringify(edits));
    } else {
      localStorage.removeItem(LIBRARY_EDITS_KEY);
    }
    return true;
  } catch {
    return false;
  }
};
