import { useEffect, useId, useMemo, useRef, useState } from 'react';
import { createPortal } from 'react-dom';
import styled from 'styled-components';

import {
  NormalizationOptions,
  Subdivision,
  getNormalizationOptions,
  normalizeMelody,
} from 'app/services/MelodiesService/normalization';
import { Melody } from 'app/services/MelodiesService/types';

import { MelodyActionButton, MelodyActionIcon } from './MelodyAction';
import { StaffLine } from './Staff/StaffLine';

interface Props {
  melody: Melody;
  canRestore: boolean;
  isPlaying: boolean;
  onApply: (options: NormalizationOptions) => void;
  onRestore: () => void;
  onPreview: (melody: Melody) => void;
  onStop: () => void;
  durationsOnly?: boolean;
  compact?: boolean;
  showLabel?: boolean;
}

export const RecordingNormalization = ({
  melody,
  canRestore,
  isPlaying,
  onApply,
  onRestore,
  onPreview,
  onStop,
  durationsOnly = false,
  compact = false,
  showLabel = false,
}: Props) => {
  const Button = compact ? MelodyActionButton : 'button';
  const [isOpen, setIsOpen] = useState(false);
  const [options, setOptions] = useState(() => ({
    ...getNormalizationOptions(melody),
    quantizeStarts: !durationsOnly,
  }));
  const trigger = useRef<HTMLButtonElement>(null);
  const currentBpm = getNormalizationOptions(melody).bpm;
  useEffect(() => {
    setOptions(previous => ({ ...previous, bpm: currentBpm }));
  }, [currentBpm]);
  const closeButton = useRef<HTMLButtonElement>(null);
  const panelId = useId();
  useEffect(() => {
    if (isOpen) closeButton.current?.focus();
  }, [isOpen]);
  const result = useMemo(
    () => normalizeMelody(melody, options),
    [melody, options],
  );
  const hasChanges =
    result.changedNotes > 0 ||
    result.removedNotes > 0 ||
    result.melody.bpm !== melody.bpm;
  const update = (patch: Partial<NormalizationOptions>) => {
    onStop();
    setOptions(current => ({ ...current, ...patch }));
  };
  const close = () => {
    onStop();
    setIsOpen(false);
    trigger.current?.focus();
  };

  return (
    <>
      <Button
        {...(compact ? { $withLabel: showLabel } : {})}
        ref={trigger}
        aria-label="Normalize"
        title="Normalize"
        aria-expanded={isOpen}
        disabled={!melody.notes.length}
        aria-controls={isOpen ? panelId : undefined}
        onClick={() => {
          if (isOpen) {
            close();
          } else {
            onStop();
            setIsOpen(true);
          }
        }}
      >
        {compact && <MelodyActionIcon action="normalize" />}
        {(!compact || showLabel) && 'Normalize'}
      </Button>
      {canRestore && (
        <Button
          {...(compact ? { $withLabel: showLabel } : {})}
          aria-label="Restore original"
          title="Restore original"
          onClick={() => {
            close();
            onRestore();
          }}
        >
          {compact && <MelodyActionIcon action="restore" />}
          {(!compact || showLabel) && 'Restore original'}
        </Button>
      )}
      {isOpen &&
        createPortal(
          <Panel
            id={panelId}
            aria-label="Normalize recording"
            onKeyDown={event => {
              if (event.key === 'Escape') close();
            }}
          >
            <Header>
              <strong>Normalize recording</strong>
              <button ref={closeButton} onClick={close}>
                Close
              </button>
            </Header>
            <p>
              Line up note timing and length with the grid without changing
              pitch. Select Apply to update the recording.
            </p>
            <Controls>
              <label>
                Tempo, BPM
                <input
                  type="number"
                  min={40}
                  max={220}
                  value={options.bpm}
                  onChange={event => update({ bpm: +event.target.value })}
                  onBlur={() => update({ bpm: result.melody.bpm! })}
                />
              </label>
              <label>
                Rhythm grid
                <select
                  value={options.subdivision}
                  onChange={event =>
                    update({ subdivision: +event.target.value as Subdivision })
                  }
                >
                  <option value={0}>No quantization</option>
                  <option value={1}>1/4</option>
                  <option value={2}>1/8</option>
                  <option value={4}>1/16</option>
                  <option value={8}>1/32</option>
                  <option value={3}>1/8 triplets</option>
                </select>
              </label>
              <label>
                <input
                  type="checkbox"
                  checked={options.quantizeStarts !== false}
                  disabled={!options.subdivision}
                  onChange={event =>
                    update({ quantizeStarts: event.target.checked })
                  }
                />
                Quantize starts
              </label>
              <label>
                <input
                  type="checkbox"
                  checked={options.quantizeDurations}
                  disabled={!options.subdivision}
                  onChange={event =>
                    update({ quantizeDurations: event.target.checked })
                  }
                />
                Quantize durations
              </label>
              <label>
                <input
                  type="checkbox"
                  checked={options.removeShortNotes}
                  onChange={event =>
                    update({ removeShortNotes: event.target.checked })
                  }
                />
                Remove short taps
              </label>
              {options.removeShortNotes && (
                <label>
                  Shorter than, ms
                  <input
                    type="number"
                    min={1}
                    max={250}
                    value={options.minDurationMs}
                    onChange={event =>
                      update({ minDurationMs: +event.target.value })
                    }
                    onBlur={() =>
                      update({
                        minDurationMs: Math.max(
                          1,
                          Math.min(250, options.minDurationMs),
                        ),
                      })
                    }
                  />
                </label>
              )}
            </Controls>
            <p role="status">
              Notes: {melody.notes.length} → {result.melody.notes.length}.
              Adjusted: {result.changedNotes}. Removed: {result.removedNotes}.
            </p>
            {!!result.preservedNotes && (
              <p>
                Fast sequences ({result.preservedNotes} notes) were kept without
                quantization to avoid turning them into chords. Try a finer grid
                for these passages.
              </p>
            )}
            <Preview aria-label="Normalization preview" tabIndex={0}>
              {result.melody.notes.length ? (
                <StaffLine
                  melody={result.melody}
                  bpm={result.melody.bpm!}
                  now={0}
                />
              ) : (
                <p>
                  All notes would be removed. Lower the short-tap threshold.
                </p>
              )}
            </Preview>
            <Controls>
              <button onClick={() => onPreview(melody)}>Play original</button>
              <button
                disabled={!result.melody.notes.length}
                onClick={() => onPreview(result.melody)}
              >
                Play result
              </button>
              <button disabled={!isPlaying} onClick={onStop}>
                Stop
              </button>
              <button
                disabled={!hasChanges || !result.melody.notes.length}
                onClick={() => {
                  close();
                  onApply(options);
                }}
              >
                Apply
              </button>
            </Controls>
          </Panel>,
          document.body,
        )}
    </>
  );
};

const Panel = styled.section`
  position: fixed;
  z-index: 1100;
  top: 58px;
  left: 75px;
  right: 24px;
  max-width: 960px;
  max-height: calc(100vh - 200px);
  overflow: auto;
  padding: 16px;
  color: ${p => p.theme.text};
  background: ${p => p.theme.surface};
  border: 1px solid ${p => p.theme.border};
  border-radius: 8px;
  box-shadow: 0 4px 24px ${p => p.theme.shadow};
  font-size: 0.85rem;
  p {
    color: ${p => p.theme.textSecondary};
  }
  input[type='number'] {
    width: 70px;
    margin-left: 6px;
  }
  select {
    margin-left: 6px;
  }
  @media (max-width: 600px) {
    left: 12px;
    right: 12px;
    top: 90px;
  }
`;

const Header = styled.div`
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
`;

const Controls = styled.div`
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px 16px;
  label {
    display: flex;
    align-items: center;
    gap: 4px;
  }
`;

const Preview = styled.div`
  overflow: auto;
  max-height: 230px;
  margin-bottom: 12px;
  --staff-background: ${p => p.theme.surface};
`;
