import { useLayoutEffect, useMemo, useRef } from 'react';
import { useSelector } from 'react-redux';
import styled from 'styled-components';

import { selectMelodies } from 'app/services/MelodiesService';
import { Phrase } from 'app/services/MelodyGenerationService/compose';
import { phraseRecordingProject } from 'app/services/MelodyGenerationService/output';

import { StaffLine } from 'app/components/Staff/StaffLine';
import { layoutStaff } from 'app/components/Staff/layout';
import { playbackX } from 'app/components/Staff/playback';

const gutter = 12;

export const MelodyGeneratorScore = ({
  phrase,
  position,
  isPlaying,
  onSeek,
}: {
  phrase: Phrase;
  position: number;
  isPlaying: boolean;
  onSeek: (time: number) => void;
}) => {
  const { soundingNoteIndices } = useSelector(selectMelodies);
  const scroll = useRef<HTMLDivElement>(null);
  const previousX = useRef<number>();
  const [staff] = useMemo(() => {
    const { tracks } = phraseRecordingProject(phrase);
    return layoutStaff(tracks[0].melody, phrase.bpm, 0, 'single-line');
  }, [phrase]);

  useLayoutEffect(() => {
    const viewport = scroll.current;
    const x = playbackX(staff, position);
    if (!isPlaying || !viewport || x === undefined) {
      previousX.current = undefined;
      return;
    }
    const cursor = x + gutter;
    const previous = previousX.current;
    previousX.current = cursor;
    const { scrollLeft, clientWidth } = viewport;
    const right = scrollLeft + clientWidth - gutter;
    // Let the user browse ahead while playing. Follow when the cursor leaves
    // the visible score, starts playing, or wraps back to the first bar.
    if (
      (cursor < scrollLeft || cursor > right) &&
      (previous === undefined ||
        cursor < previous ||
        (previous >= scrollLeft && previous <= right))
    )
      viewport.scrollLeft = Math.max(0, cursor - clientWidth / 4);
  }, [isPlaying, position, staff]);

  return (
    <section>
      <ScoreHeading>
        <h3 id="melody-score">Melody notes</h3>
        <p>Click or tap to jump. Scroll to see every bar.</p>
      </ScoreHeading>
      <ScoreScroll
        ref={scroll}
        role="region"
        aria-labelledby="melody-score"
        tabIndex={0}
      >
        <div style={{ width: staff.width }}>
          <StaffLine
            line={staff}
            bpm={phrase.bpm}
            position={position}
            soundingNoteIndices={isPlaying ? soundingNoteIndices : []}
            onSeek={onSeek}
          />
        </div>
      </ScoreScroll>
    </section>
  );
};

const ScoreHeading = styled.div`
  display: flex;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 4px 12px;
  margin-bottom: 6px;

  p {
    font-size: 13px;
  }
`;

const ScoreScroll = styled.div`
  min-width: 0;
  overflow-x: auto;
  border: 1px solid ${p => p.theme.border};
  border-radius: 8px;
  background: ${p => p.theme.background};
  --staff-background: ${p => p.theme.background};
  --staff-playback: ${p => p.theme.primary};

  > div {
    padding: 4px ${gutter}px 0;
    box-sizing: content-box;
  }
`;
